import 'package:flutter_test/flutter_test.dart';import 'package:surge_wizard/core/dungeon_run_state_v4.dart';import 'package:surge_wizard/core/vertical_slice_catalog_v4.dart';void main(){test('KO revives to 1 HP after victory carry capture',(){final w=VerticalSliceCatalogV4.wizard(),k=VerticalSliceCatalogV4.kael();k.hp=0;final c=DungeonCarryStateV4.fromParty([w,k],hpPotions:0);c.captureAfterVictory([w,k]);expect(c.party['kael']!.hp,1);});test('between fight potion consumes inventory',(){final w=VerticalSliceCatalogV4.wizard();w.hp=10;final c=DungeonCarryStateV4.fromParty([w],hpPotions:2);c.useBetweenFightPotions([w]);expect(c.hpPotions,lessThan(2));});}
